mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.z = mod(q.z, 3.0) - 1.5;
  float s = length(q) - (0.8 + 0.05 * sin(p.y * 8.0 + time * 3.0));
  float fl = p.y + 1.2;
  return min(s, fl);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.2, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 14.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.03, 0.05);
  if (t < 14.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(map(pos+e.xyy)-map(pos-e.xyy), map(pos+e.yxy)-map(pos-e.yxy), map(pos+e.yyx)-map(pos-e.yyx)));
    vec3 ref = reflect(rd, n);
    col = 0.5 + 0.5 * sin(ref * 3.0 + time * 1.5);
  }
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
